import subprocess, json, re
def run(spec):
    open('spec.json','w').write(json.dumps(spec))
    out=subprocess.run(['Rscript','scripts/fit.R','spec.json'],capture_output=True,text=True).stdout
    gaps={}
    for line in out.splitlines():
        m=re.match(r'\s+(\d+)\s+(-?[\d.]+)\s+(-?[\d.]+)\s+(-?[\d.]+)',line)
        if m:
            p=int(m.group(1)); gaps[p]=float(m.group(4))
    mse=re.search(r'prediction error over periods \d+ to \d+ ([\d.]+)',out)
    att=sum(gaps[p] for p in range(41,61))/20
    return att, float(mse.group(1)) if mse else None, gaps

base={"predictors":{"option":"every_outcome","covariate_periods":[1]},"v":{"option":"pre_period_fit"},"weights":{"option":"convex"},"penalty":{"option":"none"}}
val={"predictors":{"option":"every_outcome","covariate_periods":[1]},"v":{"option":"validation","training_end":30},"weights":{"option":"convex"},"penalty":{"option":"none"}}
dist={"predictors":{"option":"every_outcome","covariate_periods":[1]},"v":{"option":"pre_period_fit"},"weights":{"option":"convex"},"penalty":{"option":"distance","lambda":1.0}}
for name,s in [("base",base),("val",val),("dist",dist)]:
    att,mse,g=run(s)
    print(f"{name}: ATT={att:.3f} preMSE={mse}")
EOF
```

