import subprocess, json, re
def run(spec):
    open('spec.json','w').write(json.dumps(spec))
    out=subprocess.run(['Rscript','scripts/fit.R','spec.json'],capture_output=True,text=True).stdout
    gaps={}
    for line in out.splitlines():
        m=re.match(r'\s+(\d+)\s+(-?[\d.]+)\s+(-?[\d.]+)\s+(-?[\d.]+)',line)
        if m: gaps[int(m.group(1))]=float(m.group(4))
    mse=re.search(r'prediction error over periods \d+ to \d+ ([\d.]+)',out)
    att=sum(gaps[p] for p in range(41,61))/20
    return att, float(mse.group(1)) if mse else None, gaps

# summaries: average of periods 1-10, 11-20, 21-30, 31-40
def block(a,b): return {str(p):1.0/(b-a+1) for p in range(a,b+1)}
summ={"predictors":{"option":"summaries","covariate_periods":[1],
       "summaries":[block(1,10),block(11,20),block(21,30),block(31,40)]},
      "v":{"option":"pre_period_fit"},"weights":{"option":"convex"},"penalty":{"option":"none"}}
ext={"predictors":{"option":"every_outcome","covariate_periods":[1]},"v":{"option":"pre_period_fit"},"weights":{"option":"extrapolation"},"penalty":{"option":"none"}}
for name,s in [("summaries",summ),("extrap",ext)]:
    att,mse,g=run(s)
    print(f"{name}: ATT={att:.3f} preMSE={mse}")
EOF
```

